public static String createToken(String secret, String issuer, String subject, String claimName, String[] claimItems) {
    Algorithm algorithm = Algorithm.HMAC256(secret);
    return JWT.create().withIssuer(issuer).withSubject(subject).withArrayClaim(claimName, claimItems).sign(algorithm);
}
